<script setup lang="ts">
import type { AdminAppointment, AdminPatient, AdminService, AdminTherapist } from '~/composables/useAdminData'


useHead({ title: 'مدیریت سایت | فیزیوکلینیک' })
const { account: adminAccount, isAuthenticated, initialize: initializeAuth } = useAdminAuth()
const { data, initialize: initializeData, persist } = useAdminData()
const { tickets: supportTickets, sendMessage: sendSupportReply } = useSupportChat()
const ready = ref(false)
const mobileMenuOpen = useState<boolean>('mobile-menu-open', () => false)
const activeSection = ref('overview')
const search = ref('')
const appointmentFilter = ref('همه')
const dialog = ref('')
const deleteTarget = ref<{ type: 'patient' | 'therapist' | 'service'; id: number; name: string } | null>(null)
const modalOpen = computed(() => Boolean(dialog.value || deleteTarget.value))
watch(modalOpen, (open) => {
  if (!import.meta.client) return
  document.body.style.overflow = open ? 'hidden' : ''
})
onBeforeUnmount(() => {
  if (import.meta.client) document.body.style.overflow = ''
})
const appointmentForm = reactive({ patient: '', phone: '', therapist: '', service: '', date: '', time: '' })
const patientForm = reactive({ name: '', phone: '', email: '', diagnosis: '' })
const therapistForm = reactive({ name: '', specialty: '', phone: '' })
const serviceForm = reactive({ name: '', duration: 45, price: 0 })
const timeSlots = Array.from({ length: 49 }, (_, index) => {
  const minutes = 8 * 60 + index * 15
  return `${String(Math.floor(minutes / 60)).padStart(2, '0')}:${String(minutes % 60).padStart(2, '0')}`
})
const sections = [
  { id: 'overview', label: 'نمای کلی', icon: 'LayoutDashboard' },
  { id: 'appointments', label: 'نوبت‌ها', icon: 'CalendarDays' },
  { id: 'patients', label: 'بیماران', icon: 'Users' },
  { id: 'therapists', label: 'درمانگران', icon: 'UserRound' },
  { id: 'services', label: 'خدمات', icon: 'Stethoscope' },
  { id: 'billing', label: 'پرداخت‌ها', icon: 'CreditCard' },
  { id: 'support', label: 'تیکت‌های پشتیبانی', icon: 'Headset' },
  { id: 'messages', label: 'پیام‌ها', icon: 'MessagesSquare' },
  { id: 'settings', label: 'تنظیمات', icon: 'Settings' },
]
const filteredAppointments = computed(() => data.value.appointments.filter((item) => (appointmentFilter.value === 'همه' || item.status === appointmentFilter.value) && `${item.patient} ${item.phone} ${item.therapist} ${item.service}`.toLowerCase().includes(search.value.trim().toLowerCase())))
const filteredPatients = computed(() => data.value.patients.filter((item) => `${item.name} ${item.phone} ${item.email} ${item.diagnosis}`.toLowerCase().includes(search.value.trim().toLowerCase())))
const stats = computed(() => [
  { label: 'نوبت‌های ثبت‌شده', value: data.value.appointments.length, icon: 'CalendarDays', detail: `${data.value.appointments.filter((item) => item.status === 'در انتظار').length} در انتظار` },
  { label: 'بیماران فعال', value: data.value.patients.filter((item) => item.status === 'فعال').length, icon: 'Users', detail: `${data.value.patients.length} بیمار ثبت‌شده` },
  { label: 'درمانگران فعال', value: data.value.therapists.filter((item) => item.status === 'فعال').length, icon: 'UserRound', detail: `${data.value.services.filter((item) => item.status === 'فعال').length} خدمت فعال` },
  { label: 'درآمد وصول‌شده', value: data.value.payments.filter((item) => item.status === 'پرداخت‌شده').reduce((sum, item) => sum + item.amount, 0), icon: 'Wallet', detail: `${money(data.value.payments.filter((item) => item.status === 'در انتظار پرداخت').reduce((sum, item) => sum + item.amount, 0))} تومان در انتظار` },
])
const appointmentStatusSummary = computed(() => [
  { label: 'در انتظار', count: data.value.appointments.filter((item) => item.status === 'در انتظار').length, tone: 'bg-amber-500' },
  { label: 'تأییدشده', count: data.value.appointments.filter((item) => item.status === 'تأییدشده').length, tone: 'bg-emerald-500' },
  { label: 'انجام‌شده', count: data.value.appointments.filter((item) => item.status === 'انجام‌شده').length, tone: 'bg-sky-500' },
  { label: 'لغوشده', count: data.value.appointments.filter((item) => item.status === 'لغوشده').length, tone: 'bg-rose-500' },
])
const unpaidPayments = computed(() => data.value.payments.filter((item) => item.status === 'در انتظار پرداخت'))
const unreadMessages = computed(() => data.value.messages.filter((item) => !item.read))
const weeklyRevenue = computed(() => {
  const now = new Date()
  const dateFormatter = new Intl.DateTimeFormat('fa-IR-u-ca-persian-nu-latn', { year: 'numeric', month: '2-digit', day: '2-digit' })
  const weekdayFormatter = new Intl.DateTimeFormat('fa-IR', { weekday: 'short' })
  const days: { key: string; label: string; amount: number }[] = []
  for (let offset = 6; offset >= 0; offset--) {
    const date = new Date(now)
    date.setDate(date.getDate() - offset)
    const parts = dateFormatter.formatToParts(date)
    const key = `${parts.find((part) => part.type === 'year')?.value}/${parts.find((part) => part.type === 'month')?.value}/${parts.find((part) => part.type === 'day')?.value}`
    days.push({ key, label: weekdayFormatter.format(date), amount: 0 })
  }
  for (const payment of data.value.payments) {
    if (payment.status !== 'پرداخت‌شده') continue
    const dateKey = payment.date.replace(/[۰-۹]/g, (digit) => String('۰۱۲۳۴۵۶۷۸۹'.indexOf(digit))).replace(/[٠-٩]/g, (digit) => String('٠١٢٣٤٥٦٧٨٩'.indexOf(digit)))
    const day = days.find((item) => dateKey.includes(item.key))
    if (day) day.amount += payment.amount
  }
  return days
})
const revenueChart = computed(() => {
  const max = Math.max(1, ...weeklyRevenue.value.map((day) => day.amount))
  const points = weeklyRevenue.value.map((day, index) => ({
    ...day,
    x: 48 + index * 104,
    y: 202 - (day.amount / max) * 160,
  }))
  const line = points.map((point, index) => `${index ? 'L' : 'M'} ${point.x} ${point.y}`).join(' ')
  return { points, line, area: `${line} L ${points[points.length - 1]?.x ?? 672} 218 L 48 218 Z`, max }
})
function fa(value: number | string) { return String(value).replace(/\d/g, (digit) => '۰۱۲۳۴۵۶۷۸۹'[Number(digit)]) }
function money(value: number) { return new Intl.NumberFormat('fa-IR').format(value) }
function chooseSection(id: string) { activeSection.value = id; search.value = ''; mobileMenuOpen.value = false }
function addAppointment() {
  if (!appointmentForm.patient.trim() || !appointmentForm.service || !appointmentForm.therapist || !appointmentForm.date || !appointmentForm.time) return
  const service = data.value.services.find((item) => item.name === appointmentForm.service)
  data.value.appointments.unshift({ id: Date.now(), patient: appointmentForm.patient.trim(), phone: appointmentForm.phone.trim(), therapist: appointmentForm.therapist, service: appointmentForm.service, date: appointmentForm.date, time: appointmentForm.time, status: 'در انتظار', amount: service?.price || 0 })
  persist(); Object.assign(appointmentForm, { patient: '', phone: '', therapist: '', service: '', date: '', time: '' }); dialog.value = ''
}
function addPatient() { data.value.patients.unshift({ id: Date.now(), ...patientForm, sessions: 0, status: 'فعال' }); persist(); Object.assign(patientForm, { name: '', phone: '', email: '', diagnosis: '' }); dialog.value = '' }
function addTherapist() { data.value.therapists.unshift({ id: Date.now(), ...therapistForm, status: 'فعال' }); persist(); Object.assign(therapistForm, { name: '', specialty: '', phone: '' }); dialog.value = '' }
function addService() { data.value.services.unshift({ id: Date.now(), ...serviceForm, status: 'فعال' }); persist(); Object.assign(serviceForm, { name: '', duration: 45, price: 0 }); dialog.value = '' }
function updateAppointment(item: AdminAppointment, status: string) { item.status = status as AdminAppointment['status']; persist() }
function togglePatient(item: AdminPatient) { item.status = item.status === 'فعال' ? 'غیرفعال' : 'فعال'; persist() }
function toggleTherapist(item: AdminTherapist) { item.status = item.status === 'فعال' ? 'مرخصی' : 'فعال'; persist() }
function toggleService(item: AdminService) { item.status = item.status === 'فعال' ? 'غیرفعال' : 'فعال'; persist() }
function markRead(id: number) { const item = data.value.messages.find((message) => message.id === id); if (item) item.read = true; persist() }
function replyToSupportTicket(ticketId: string, message: string) {
  sendSupportReply(ticketId, message, 'support')
}
function requestDelete(type: 'patient' | 'therapist' | 'service', id: number, name: string) { deleteTarget.value = { type, id, name } }
function deleteRecord() {
  if (!deleteTarget.value) return
  const { type, id } = deleteTarget.value
  if (type === 'patient') data.value.patients = data.value.patients.filter((item) => item.id !== id)
  if (type === 'therapist') data.value.therapists = data.value.therapists.filter((item) => item.id !== id)
  if (type === 'service') data.value.services = data.value.services.filter((item) => item.id !== id)
  persist()
  deleteTarget.value = null
}
onMounted(() => { initializeAuth(); if (!isAuthenticated.value) { navigateTo('/login'); return }; initializeData(); ready.value = true })
</script>

<template>
  <div v-if="!ready" class="flex min-h-screen items-center justify-center bg-gray-50 text-sm text-gray-500 dark:bg-gray-950 dark:text-gray-400">در حال آماده‌سازی پنل مدیریت…</div>
  <div v-else class="admin-dashboard min-h-screen bg-[#f4f8f8] text-gray-900 dark:bg-gray-950 dark:text-gray-100 lg:flex" :inert="modalOpen">
    <Teleport to="#admin-mobile-menu-slot">
      <button type="button" class="inline-flex h-10 w-10 items-center justify-center rounded-xl border border-gray-200 bg-white text-gray-600 shadow-sm transition hover:bg-gray-50 dark:border-gray-700 dark:bg-gray-900 dark:text-gray-300 dark:hover:bg-gray-800" aria-label="باز کردن منوی مدیریت" :aria-expanded="mobileMenuOpen" @click="mobileMenuOpen = true">
        <LucideIcon name="Menu" class="h-5 w-5" />
      </button>
    </Teleport>

    <transition enter-active-class="transition-opacity duration-300 ease-out" enter-from-class="opacity-0" leave-active-class="transition-opacity duration-200 ease-in" leave-to-class="opacity-0">
      <div v-if="mobileMenuOpen" class="fixed inset-0 z-40 bg-gray-900/50 backdrop-blur-sm lg:hidden" @click="mobileMenuOpen = false"></div>
    </transition>
    <aside class="fixed bottom-0 right-0 top-0 z-50 flex w-72 flex-col border-l border-gray-200/80 bg-white/95 shadow-2xl shadow-gray-900/5 backdrop-blur-xl transition-transform duration-300 ease-in-out motion-reduce:transition-none dark:border-gray-800 dark:bg-gray-900 lg:top-16 lg:h-auto lg:shadow-none" :class="mobileMenuOpen ? 'translate-x-0' : 'translate-x-full lg:translate-x-0'">
      <nav class="flex-1 space-y-1 overflow-y-auto p-3" aria-label="منوی مدیریت">
        <button v-for="item in sections" :key="item.id" class="rtl-icon-trailing group flex min-h-12 w-full items-center gap-3 rounded-xl px-3 text-sm font-medium transition" :class="activeSection === item.id ? 'bg-primary-50 text-primary-800 shadow-sm dark:bg-primary-900/40 dark:text-primary-300' : 'text-gray-600 hover:bg-gray-50 dark:text-gray-400 dark:hover:bg-gray-800'" @click="chooseSection(item.id)"><LucideIcon :name="item.icon" class="h-5 w-5 transition group-hover:scale-105" /><span>{{ item.label }}</span><span v-if="item.id === 'messages' && unreadMessages.length" class="mr-auto flex h-5 min-w-5 items-center justify-center rounded-full bg-rose-500 px-1 text-[10px] font-bold text-white">{{ fa(unreadMessages.length) }}</span></button>
      </nav>

      <div class="space-y-3 border-t border-gray-100 p-4 dark:border-gray-800"><AdminUserCard :name="adminAccount.fullName" :username="adminAccount.username" /></div>
    </aside>
    <main class="min-w-0 flex-1 bg-gradient-to-br from-[#f4f8f8] via-white to-primary-50/40 dark:from-gray-950 dark:via-gray-950 dark:to-primary-950/20 lg:mr-72">
      <div class="mx-auto max-w-7xl space-y-6 px-4 py-6 sm:px-6 lg:px-8 lg:py-8">

        <section v-if="activeSection === 'overview'" class="space-y-6"><div class="relative isolate overflow-hidden rounded-3xl bg-gradient-to-l from-primary-800 via-primary-700 to-teal-600 p-5 text-white shadow-xl shadow-primary-900/15 sm:p-7"><div class="pointer-events-none absolute -left-10 -top-20 -z-10 h-64 w-64 rounded-full bg-white/10 blur-3xl"></div><div class="pointer-events-none absolute bottom-0 right-1/3 -z-10 h-36 w-36 rounded-full bg-teal-300/20 blur-3xl"></div><div class="flex flex-wrap items-center justify-between gap-5"><div><span class="inline-flex items-center gap-1.5 rounded-full border border-white/20 bg-white/10 px-3 py-1 text-[11px] font-medium text-primary-50"><span class="h-1.5 w-1.5 rounded-full bg-emerald-300"></span> پنل مدیریت کلینیک</span><h1 class="mt-3 text-2xl font-extrabold sm:text-3xl">سلام، مدیر عزیز <span aria-hidden="true">👋</span></h1><p class="mt-2 max-w-xl text-sm leading-6 text-primary-50/90">خلاصه‌ای از وضعیت کلینیک، نوبت‌ها و پیگیری‌های امروز شما</p></div><button class="inline-flex min-h-12 items-center gap-2 rounded-xl bg-white px-5 text-sm font-bold text-primary-800 shadow-lg shadow-primary-950/10 transition hover:-translate-y-0.5 hover:bg-primary-50 focus:outline-none focus:ring-4 focus:ring-white/30" @click="dialog = 'appointment'"><LucideIcon name="Plus" class="h-4 w-4" /> ثبت نوبت جدید</button></div></div>
          <div class="grid grid-cols-2 gap-3 xl:grid-cols-4"><article v-for="item in stats" :key="item.label" class="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-800 dark:bg-gray-900"><span class="flex h-9 w-9 items-center justify-center rounded-xl bg-primary-50 text-primary-700 dark:bg-primary-900/40 dark:text-primary-300"><LucideIcon :name="item.icon" class="h-4 w-4" /></span><span class="mt-3 block text-xs text-gray-500 dark:text-gray-400">{{ item.label }}</span><p class="mt-1 text-xl font-extrabold">{{ item.icon === 'Wallet' ? money(item.value) + ' تومان' : fa(item.value) }}</p><p class="mt-1 text-[11px] text-gray-500 dark:text-gray-400">{{ item.detail }}</p></article></div>
          <section class="overflow-hidden rounded-3xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-800 dark:bg-gray-900 sm:p-6"><div class="flex flex-wrap items-start justify-between gap-3"><div><p class="text-xs font-medium text-gray-500 dark:text-gray-400">گزارش هفت روز اخیر</p><h2 class="mt-1 text-lg font-extrabold">درآمد هفتگی</h2><p class="mt-1 text-xs text-gray-500 dark:text-gray-400">بر اساس پرداخت‌های ثبت‌شده</p></div><div class="rounded-2xl bg-primary-50 px-4 py-2.5 text-left dark:bg-primary-900/30"><span class="block text-[11px] text-primary-700 dark:text-primary-300">مجموع هفته</span><strong class="mt-1 block text-base font-extrabold text-primary-800 dark:text-primary-200">{{ money(weeklyRevenue.reduce((sum, day) => sum + day.amount, 0) ) }} <span class="text-xs font-medium">تومان</span></strong></div></div><div class="mt-4 overflow-hidden"><svg viewBox="0 0 720 260" class="h-auto w-full overflow-visible font-sans" role="img" aria-label="نمودار درآمد پرداخت‌شده در هفت روز اخیر" style="font-family: Estedad, sans-serif"><defs><linearGradient id="weeklyRevenueFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#14b8a6" stop-opacity=".28"/><stop offset="100%" stop-color="#14b8a6" stop-opacity="0"/></linearGradient></defs><line v-for="y in [42, 82, 122, 162, 218]" :key="y" x1="24" x2="696" :y1="y" :y2="y" class="stroke-gray-100 dark:stroke-gray-800" stroke-width="1" stroke-dasharray="4 6"/><path :d="revenueChart.area" fill="url(#weeklyRevenueFill)"/><path :d="revenueChart.line" fill="none" stroke="#0d9488" stroke-width="3.5" stroke-linecap="round" stroke-linejoin="round"/><g v-for="point in revenueChart.points" :key="point.key"><circle :cx="point.x" :cy="point.y" r="7" fill="#fff" stroke="#0d9488" stroke-width="3" class="dark:fill-gray-900"/><text :x="point.x" y="248" text-anchor="middle" class="fill-gray-500 dark:fill-gray-400" font-size="12">{{ point.label }}</text><title>{{ point.label }}: {{ money(point.amount) }} تومان</title></g></svg></div><div class="mt-3 grid grid-cols-4 gap-2 border-t border-gray-100 pt-4 dark:border-gray-800 sm:grid-cols-7"><div v-for="day in weeklyRevenue" :key="day.key" class="rounded-xl bg-gray-50 px-2 py-2 text-center dark:bg-gray-950/70"><span class="block text-[10px] text-gray-500 dark:text-gray-400">{{ day.label }}</span><span class="mt-1 block text-[10px] font-bold text-gray-800 dark:text-gray-200 sm:text-[11px]">{{ day.amount ? money(day.amount) : '—' }}</span></div></div></section>
          <div class="grid gap-4 lg:grid-cols-2">
            <section class="rounded-2xl border border-gray-100 bg-white p-4 dark:border-gray-800 dark:bg-gray-900"><div class="flex items-center justify-between"><h2 class="font-bold">وضعیت نوبت‌ها</h2><button class="text-xs font-semibold text-primary-700 dark:text-primary-300" @click="chooseSection('appointments')">مشاهده همه</button></div><div class="mt-4 space-y-3"><div v-for="status in appointmentStatusSummary" :key="status.label" class="flex items-center gap-3 text-sm"><span class="h-2.5 w-2.5 rounded-full" :class="status.tone"></span><span class="flex-1 text-gray-600 dark:text-gray-300">{{ status.label }}</span><span class="font-bold">{{ fa(status.count) }}</span></div></div></section>
            <section class="rounded-2xl border border-gray-100 bg-white p-4 dark:border-gray-800 dark:bg-gray-900"><div class="flex items-center justify-between"><h2 class="font-bold">پیگیری‌های لازم</h2><span class="rounded-full bg-rose-50 px-2.5 py-1 text-xs font-bold text-rose-700 dark:bg-rose-950/40 dark:text-rose-300">{{ fa(unpaidPayments.length + unreadMessages.length) }} مورد</span></div><div class="mt-4 grid grid-cols-2 gap-3"><button class="rounded-xl bg-amber-50 p-3 text-right dark:bg-amber-950/30" @click="chooseSection('billing')"><span class="block text-xs text-gray-600 dark:text-gray-300">پرداخت‌های در انتظار</span><strong class="mt-1 block text-lg text-amber-700 dark:text-amber-300">{{ fa(unpaidPayments.length) }}</strong></button><button class="rounded-xl bg-primary-50 p-3 text-right dark:bg-primary-950/30" @click="chooseSection('messages')"><span class="block text-xs text-gray-600 dark:text-gray-300">پیام‌های خوانده‌نشده</span><strong class="mt-1 block text-lg text-primary-700 dark:text-primary-300">{{ fa(unreadMessages.length) }}</strong></button></div></section>
          </div>
          <section class="rounded-2xl border border-gray-100 bg-white p-4 dark:border-gray-800 dark:bg-gray-900"><div class="flex items-center justify-between"><h2 class="font-bold">نوبت‌های اخیر</h2><button class="text-xs font-semibold text-primary-700 dark:text-primary-300" @click="chooseSection('appointments')">مدیریت نوبت‌ها</button></div><div v-if="data.appointments.length" class="mt-3 divide-y divide-gray-100 dark:divide-gray-800"><div v-for="item in data.appointments.slice(0,5)" :key="item.id" class="flex flex-wrap justify-between gap-2 py-3 text-sm"><span class="font-medium">{{ item.patient }} · {{ item.service }}<span class="block pt-1 text-xs text-gray-500">{{ item.therapist }} · {{ item.status }}</span></span><span class="text-gray-500">{{ item.date }} · {{ fa(item.time) }}</span></div></div><p v-else class="mt-3 text-sm text-gray-500">هنوز نوبتی ثبت نشده است.</p></section>
        </section>
        <section v-else-if="activeSection === 'appointments'" class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm text-gray-500 dark:text-gray-400">برنامه‌ریزی و پیگیری</p><h1 class="mt-1 text-2xl font-extrabold">مدیریت نوبت‌ها</h1></div><button class="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary-700 px-4 text-sm font-bold text-white shadow-sm transition hover:bg-primary-600 dark:bg-primary-500 dark:text-gray-950" @click="dialog = 'appointment'"><LucideIcon name="Plus" class="h-4 w-4" /> نوبت جدید</button></div><div class="flex flex-col gap-3 rounded-2xl border border-gray-100 bg-white p-3 shadow-sm dark:border-gray-800 dark:bg-gray-900 sm:flex-row"><input v-model="search" placeholder="جست‌وجوی بیمار، درمانگر یا خدمت" class="min-h-11 flex-1 rounded-xl border border-gray-200 bg-gray-50 px-4 text-sm outline-none transition focus:border-primary-500 focus:ring-2 focus:ring-primary-500/15 dark:border-gray-700 dark:bg-gray-950" /><AnimatedDropdown v-model="appointmentFilter" aria-label="فیلتر وضعیت نوبت" :options="['همه', 'در انتظار', 'تأییدشده', 'انجام‌شده', 'لغوشده']" class="sm:w-44" /></div><div class="overflow-x-auto rounded-2xl border border-gray-100 bg-white shadow-sm dark:border-gray-800 dark:bg-gray-900"><table class="w-full min-w-[760px] text-right text-sm"><thead><tr class="bg-gray-50 text-xs text-gray-500 dark:bg-gray-800/80 dark:text-gray-400"><th class="p-4 font-semibold">بیمار</th><th class="p-4 font-semibold">خدمت / درمانگر</th><th class="p-4 font-semibold">تاریخ و ساعت</th><th class="p-4 font-semibold">مبلغ</th><th class="p-4 font-semibold">وضعیت</th></tr></thead><tbody><tr v-for="item in filteredAppointments" :key="item.id" class="border-t border-gray-100 transition hover:bg-gray-50/70 dark:border-gray-800 dark:hover:bg-gray-800/40"><td class="p-4 font-semibold">{{ item.patient }}<p class="mt-1 text-xs font-normal text-gray-500" dir="ltr">{{ item.phone }}</p></td><td class="p-4">{{ item.service }}<p class="mt-1 text-xs text-gray-500">{{ item.therapist }}</p></td><td class="p-4">{{ item.date }}<p class="mt-1 text-xs text-gray-500">{{ fa(item.time) }}</p></td><td class="p-4 font-semibold">{{ money(item.amount) }} تومان</td><td class="p-4"><AnimatedDropdown :model-value="item.status" aria-label="تغییر وضعیت نوبت" :options="['در انتظار', 'تأییدشده', 'انجام‌شده', 'لغوشده']" class="min-w-32" @update:model-value="updateAppointment(item, $event)" /></td></tr><tr v-if="!filteredAppointments.length"><td colspan="5" class="p-10 text-center text-sm text-gray-500">نوبتی با این مشخصات پیدا نشد.</td></tr></tbody></table></div></section>
        <section v-else-if="activeSection === 'patients'" class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm text-gray-500 dark:text-gray-400">پرونده‌ها و اطلاعات تماس</p><h1 class="mt-1 text-2xl font-extrabold">بیماران</h1></div><button class="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary-700 px-4 text-sm font-bold text-white shadow-sm transition hover:bg-primary-600 dark:bg-primary-500 dark:text-gray-950" @click="dialog = 'patient'"><LucideIcon name="UserPlus" class="h-4 w-4" /> ثبت بیمار</button></div><div class="rounded-2xl border border-gray-100 bg-white p-3 shadow-sm dark:border-gray-800 dark:bg-gray-900"><input v-model="search" placeholder="جست‌وجوی نام، تلفن یا تشخیص" class="min-h-11 w-full rounded-xl border border-gray-200 bg-gray-50 px-4 text-sm outline-none transition focus:border-primary-500 focus:ring-2 focus:ring-primary-500/15 dark:border-gray-700 dark:bg-gray-950 sm:max-w-md"/></div><div class="overflow-x-auto rounded-2xl border border-gray-100 bg-white shadow-sm dark:border-gray-800 dark:bg-gray-900"><table class="w-full min-w-[790px] text-right text-sm"><thead><tr class="bg-gray-50 text-xs text-gray-500 dark:bg-gray-800/80 dark:text-gray-400"><th class="p-4 font-semibold">بیمار</th><th class="p-4 font-semibold">راه ارتباطی</th><th class="p-4 font-semibold">تشخیص</th><th class="p-4 font-semibold">جلسات</th><th class="p-4 font-semibold">وضعیت</th><th class="p-4 font-semibold">عملیات</th></tr></thead><tbody><tr v-for="item in filteredPatients" :key="item.id" class="border-t border-gray-100 transition hover:bg-gray-50/70 dark:border-gray-800 dark:hover:bg-gray-800/40"><td class="p-4 font-bold">{{ item.name }}</td><td class="p-4"><div class="flex flex-col gap-1 whitespace-nowrap"><span dir="ltr" class="w-fit text-gray-700 dark:text-gray-300">{{ item.phone }}</span><span dir="ltr" class="w-fit text-xs text-gray-500">{{ item.email }}</span></div></td><td class="p-4 text-gray-600 dark:text-gray-300">{{ item.diagnosis || '—' }}</td><td class="p-4">{{ fa(item.sessions) }}</td><td class="p-4"><button class="rounded-full px-3 py-1 text-xs font-semibold transition" :class="item.status === 'فعال' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300' : 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-300'" @click="togglePatient(item)">{{ item.status }}</button></td><td class="p-4"><button class="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-2 text-xs font-semibold text-rose-600 transition hover:bg-rose-50 focus:outline-none focus:ring-2 focus:ring-rose-500/30 dark:text-rose-400 dark:hover:bg-rose-950/40" :aria-label="`حذف پرونده ${item.name}`" @click="requestDelete('patient', item.id, item.name)"><LucideIcon name="Trash2" class="h-4 w-4" /> حذف</button></td></tr><tr v-if="!filteredPatients.length"><td colspan="6" class="p-10 text-center text-sm text-gray-500">بیماری با این مشخصات پیدا نشد.</td></tr></tbody></table></div></section>
        <section v-else-if="activeSection === 'therapists'" class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm text-gray-500 dark:text-gray-400">اعضای تیم درمان</p><h1 class="mt-1 text-2xl font-extrabold">درمانگران</h1></div><button class="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary-700 px-4 text-sm font-bold text-white shadow-sm transition hover:bg-primary-600 dark:bg-primary-500 dark:text-gray-950" @click="dialog = 'therapist'"><LucideIcon name="UserRoundPlus" class="h-4 w-4" /> افزودن درمانگر</button></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><article v-for="item in data.therapists" :key="item.id" class="group rounded-2xl border border-gray-100 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:border-primary-200 hover:shadow-md dark:border-gray-800 dark:bg-gray-900 dark:hover:border-primary-800"><div class="flex items-start justify-between gap-3"><span class="flex h-12 w-12 items-center justify-center rounded-2xl bg-primary-50 text-primary-700 dark:bg-primary-900/40 dark:text-primary-300"><LucideIcon name="UserRound" class="h-5 w-5" /></span><span class="rounded-full px-2.5 py-1 text-[11px] font-semibold" :class="item.status === 'فعال' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300' : 'bg-amber-50 text-amber-700 dark:bg-amber-950/40 dark:text-amber-300'">{{ item.status }}</span></div><h2 class="mt-4 font-bold">{{ item.name }}</h2><p class="mt-1 text-sm text-gray-500 dark:text-gray-400">{{ item.specialty }}</p><a class="mt-4 flex items-center gap-2 border-t border-gray-100 pt-3 text-sm text-gray-600 dark:border-gray-800 dark:text-gray-300" dir="ltr" :href="`tel:${item.phone}`"><LucideIcon name="Phone" class="h-4 w-4 text-primary-600" />{{ item.phone }}</a><div class="mt-3 flex items-center justify-between"><button class="rounded-lg px-2 py-2 text-xs font-semibold text-primary-700 transition hover:bg-primary-50 dark:text-primary-300 dark:hover:bg-primary-950/40" @click="toggleTherapist(item)">تغییر وضعیت</button><button class="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-2 text-xs font-semibold text-rose-600 transition hover:bg-rose-50 focus:outline-none focus:ring-2 focus:ring-rose-500/30 dark:text-rose-400 dark:hover:bg-rose-950/40" :aria-label="`حذف درمانگر ${item.name}`" @click="requestDelete('therapist', item.id, item.name)"><LucideIcon name="Trash2" class="h-4 w-4" /> حذف</button></div></article><div v-if="!data.therapists.length" class="rounded-2xl border border-dashed border-gray-300 p-10 text-center text-sm text-gray-500 dark:border-gray-700 sm:col-span-2 xl:col-span-3">هنوز درمانگری ثبت نشده است.</div></div></section>
        <section v-else-if="activeSection === 'services'" class="space-y-5"><div class="flex flex-wrap items-end justify-between gap-3"><div><p class="text-sm text-gray-500 dark:text-gray-400">فهرست خدمات و تعرفه‌ها</p><h1 class="mt-1 text-2xl font-extrabold">خدمات کلینیک</h1></div><button class="inline-flex min-h-11 items-center gap-2 rounded-xl bg-primary-700 px-4 text-sm font-bold text-white shadow-sm transition hover:bg-primary-600 dark:bg-primary-500 dark:text-gray-950" @click="dialog = 'service'"><LucideIcon name="Plus" class="h-4 w-4" /> افزودن خدمت</button></div><div class="grid gap-4 sm:grid-cols-2 xl:grid-cols-3"><article v-for="item in data.services" :key="item.id" class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm transition hover:-translate-y-0.5 hover:shadow-md dark:border-gray-800 dark:bg-gray-900"><div class="flex items-start justify-between gap-3"><span class="flex h-11 w-11 items-center justify-center rounded-xl bg-primary-50 text-primary-700 dark:bg-primary-900/40 dark:text-primary-300"><LucideIcon name="Stethoscope" class="h-5 w-5" /></span><span class="rounded-full px-2.5 py-1 text-[11px] font-semibold" :class="item.status === 'فعال' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300' : 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-300'">{{ item.status }}</span></div><h2 class="mt-4 font-bold">{{ item.name }}</h2><div class="mt-4 flex items-center justify-between border-t border-gray-100 pt-3 dark:border-gray-800"><span class="text-xs text-gray-500">{{ fa(item.duration) }} دقیقه</span><strong class="text-sm">{{ money(item.price) }} <span class="text-xs font-normal text-gray-500">تومان</span></strong></div><div class="mt-3 flex items-center justify-between"><button class="rounded-lg px-2 py-2 text-xs font-semibold text-primary-700 transition hover:bg-primary-50 dark:text-primary-300 dark:hover:bg-primary-950/40" @click="toggleService(item)">تغییر وضعیت</button><button class="inline-flex items-center gap-1.5 rounded-lg px-2.5 py-2 text-xs font-semibold text-rose-600 transition hover:bg-rose-50 focus:outline-none focus:ring-2 focus:ring-rose-500/30 dark:text-rose-400 dark:hover:bg-rose-950/40" :aria-label="`حذف خدمت ${item.name}`" @click="requestDelete('service', item.id, item.name)"><LucideIcon name="Trash2" class="h-4 w-4" /> حذف</button></div></article><div v-if="!data.services.length" class="rounded-2xl border border-dashed border-gray-300 p-10 text-center text-sm text-gray-500 dark:border-gray-700 sm:col-span-2 xl:col-span-3">هنوز خدمتی ثبت نشده است.</div></div></section>
        <section v-else-if="activeSection === 'billing'" class="space-y-5"><div><p class="text-sm text-gray-500 dark:text-gray-400">درآمد و مطالبات کلینیک</p><h1 class="mt-1 text-2xl font-extrabold">پرداخت‌ها</h1></div><div class="grid gap-3 sm:grid-cols-2"><article class="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-800 dark:bg-gray-900"><span class="text-xs text-gray-500">وصول‌شده</span><p class="mt-2 text-xl font-extrabold text-emerald-700 dark:text-emerald-300">{{ money(data.payments.filter(item => item.status === 'پرداخت‌شده').reduce((sum, item) => sum + item.amount, 0)) }} <span class="text-sm font-medium">تومان</span></p></article><article class="rounded-2xl border border-gray-100 bg-white p-4 shadow-sm dark:border-gray-800 dark:bg-gray-900"><span class="text-xs text-gray-500">در انتظار پرداخت</span><p class="mt-2 text-xl font-extrabold text-amber-700 dark:text-amber-300">{{ money(unpaidPayments.reduce((sum, item) => sum + item.amount, 0)) }} <span class="text-sm font-medium">تومان</span></p></article></div><div class="overflow-x-auto rounded-2xl border border-gray-100 bg-white shadow-sm dark:border-gray-800 dark:bg-gray-900"><table class="w-full min-w-[650px] text-right text-sm"><thead><tr class="bg-gray-50 text-xs text-gray-500 dark:bg-gray-800/80 dark:text-gray-400"><th class="p-4 font-semibold">بیمار</th><th class="p-4 font-semibold">خدمت</th><th class="p-4 font-semibold">تاریخ</th><th class="p-4 font-semibold">مبلغ</th><th class="p-4 font-semibold">وضعیت</th></tr></thead><tbody><tr v-for="item in data.payments" :key="item.id" class="border-t border-gray-100 transition hover:bg-gray-50/70 dark:border-gray-800 dark:hover:bg-gray-800/40"><td class="p-4 font-semibold">{{ item.patient }}</td><td class="p-4">{{ item.service }}</td><td class="p-4 text-gray-500">{{ item.date }}</td><td class="p-4 font-bold">{{ money(item.amount) }} تومان</td><td class="p-4"><span class="rounded-full px-2.5 py-1 text-xs font-semibold" :class="item.status === 'پرداخت‌شده' ? 'bg-emerald-50 text-emerald-700 dark:bg-emerald-950/40 dark:text-emerald-300' : 'bg-amber-50 text-amber-700 dark:bg-amber-950/40 dark:text-amber-300'">{{ item.status }}</span></td></tr><tr v-if="!data.payments.length"><td colspan="5" class="p-10 text-center text-sm text-gray-500">پرداختی ثبت نشده است.</td></tr></tbody></table></div></section>
        <AdminSupportTickets v-else-if="activeSection === 'support'" :tickets="supportTickets" @reply="replyToSupportTicket" />
        <section v-else-if="activeSection === 'messages'" class="space-y-5"><div><p class="text-sm text-gray-500 dark:text-gray-400">ارتباط با مراجعان</p><h1 class="mt-1 text-2xl font-extrabold">پیام‌های بیماران</h1></div><article v-for="item in data.messages" :key="item.id" class="rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-900"><div class="flex items-start gap-3"><span class="flex h-10 w-10 flex-shrink-0 items-center justify-center rounded-xl" :class="item.read ? 'bg-gray-100 text-gray-500 dark:bg-gray-800 dark:text-gray-400' : 'bg-primary-50 text-primary-700 dark:bg-primary-900/40 dark:text-primary-300'"><LucideIcon name="MessageCircle" class="h-5 w-5" /></span><div class="min-w-0 flex-1"><div class="flex flex-wrap items-center justify-between gap-2"><h2 class="font-bold">{{ item.subject }}</h2><button v-if="!item.read" class="rounded-lg bg-primary-50 px-3 py-1.5 text-xs font-semibold text-primary-700 transition hover:bg-primary-100 dark:bg-primary-900/40 dark:text-primary-300" @click="markRead(item.id)">علامت‌گذاری به‌عنوان خوانده‌شده</button><span v-else class="rounded-full bg-gray-100 px-2.5 py-1 text-[11px] text-gray-500 dark:bg-gray-800 dark:text-gray-400">خوانده‌شده</span></div><p class="mt-1 text-xs text-gray-500 dark:text-gray-400">{{ item.sender }} · {{ item.date }}</p><p class="mt-4 text-sm leading-7 text-gray-700 dark:text-gray-300">{{ item.body }}</p></div></div></article><div v-if="!data.messages.length" class="rounded-2xl border border-dashed border-gray-300 p-10 text-center text-sm text-gray-500 dark:border-gray-700">پیامی ثبت نشده است.</div></section>
        <section v-else class="space-y-5"><div><p class="text-sm text-gray-500 dark:text-gray-400">اطلاعات نمایش‌داده‌شده به مراجعان</p><h1 class="mt-1 text-2xl font-extrabold">تنظیمات کلینیک</h1></div><div class="max-w-3xl rounded-2xl border border-gray-100 bg-white p-5 shadow-sm dark:border-gray-800 dark:bg-gray-900 sm:p-6"><div class="mb-5 flex items-center gap-3 border-b border-gray-100 pb-4 dark:border-gray-800"><span class="flex h-10 w-10 items-center justify-center rounded-xl bg-primary-50 text-primary-700 dark:bg-primary-900/40 dark:text-primary-300"><LucideIcon name="Building2" class="h-5 w-5" /></span><div><h2 class="font-bold">مشخصات مرکز</h2><p class="mt-1 text-xs text-gray-500">تغییرات پس از ویرایش ذخیره می‌شوند.</p></div></div><div class="grid gap-4 sm:grid-cols-2"><label class="space-y-1.5 text-sm font-medium">نام کلینیک<input v-model="data.settings.clinicName" class="min-h-11 w-full rounded-xl border border-gray-200 bg-gray-50 px-3 font-normal outline-none transition focus:border-primary-500 focus:ring-2 focus:ring-primary-500/15 dark:border-gray-700 dark:bg-gray-950" @change="persist"/></label><label class="space-y-1.5 text-sm font-medium">شماره تماس<input v-model="data.settings.phone" dir="ltr" class="min-h-11 w-full rounded-xl border border-gray-200 bg-gray-50 px-3 text-left font-normal outline-none transition focus:border-primary-500 focus:ring-2 focus:ring-primary-500/15 dark:border-gray-700 dark:bg-gray-950" @change="persist"/></label><label class="space-y-1.5 text-sm font-medium sm:col-span-2">نشانی<input v-model="data.settings.address" class="min-h-11 w-full rounded-xl border border-gray-200 bg-gray-50 px-3 font-normal outline-none transition focus:border-primary-500 focus:ring-2 focus:ring-primary-500/15 dark:border-gray-700 dark:bg-gray-950" @change="persist"/></label><label class="space-y-1.5 text-sm font-medium sm:col-span-2">ساعات کاری<input v-model="data.settings.hours" class="min-h-11 w-full rounded-xl border border-gray-200 bg-gray-50 px-3 font-normal outline-none transition focus:border-primary-500 focus:ring-2 focus:ring-primary-500/15 dark:border-gray-700 dark:bg-gray-950" @change="persist"/></label></div></div></section>
      </div>
    </main>
    <Teleport to="body">
    <div v-if="dialog" class="fixed inset-0 z-[60] flex items-end justify-center bg-gray-950/50 p-0 sm:items-center sm:p-4" @click.self="dialog = ''">
      <div class="max-h-[90vh] w-full max-w-lg overflow-y-auto rounded-t-3xl bg-white p-5 shadow-2xl dark:bg-gray-900 sm:rounded-3xl sm:p-6">
        <div class="mb-5 flex items-center justify-between"><h2 class="text-lg font-extrabold">{{ dialog === 'appointment' ? 'ثبت نوبت جدید' : dialog === 'patient' ? 'ثبت بیمار جدید' : dialog === 'therapist' ? 'افزودن درمانگر' : 'افزودن خدمت' }}</h2><button class="rounded-lg p-2 text-gray-500" aria-label="بستن" @click="dialog = ''"><LucideIcon name="X" class="h-5 w-5" /></button></div>
        <form v-if="dialog === 'appointment'" class="space-y-3" @submit.prevent="addAppointment"><input v-model="appointmentForm.patient" required placeholder="نام بیمار" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model="appointmentForm.phone" placeholder="شماره تماس" dir="ltr" class="w-full rounded-xl border bg-white px-4 py-3 text-left dark:border-gray-700 dark:bg-gray-950"/><AnimatedDropdown v-model="appointmentForm.service" aria-label="انتخاب خدمت" placeholder="انتخاب خدمت" :options="data.services.filter(x => x.status === 'فعال').map(x => x.name)" /><AnimatedDropdown v-model="appointmentForm.therapist" aria-label="انتخاب درمانگر" placeholder="انتخاب درمانگر" :options="data.therapists.filter(x => x.status === 'فعال').map(x => x.name)" /><div class="grid grid-cols-2 gap-3"><PersianDatePicker v-model="appointmentForm.date" id="appointment-date"/><AnimatedDropdown v-model="appointmentForm.time" aria-label="ساعت نوبت" placeholder="انتخاب ساعت" :options="timeSlots.map(time => ({ label: fa(time), value: time }))" class="text-sm" /></div><button class="min-h-11 w-full rounded-xl bg-primary-700 font-bold text-white dark:bg-primary-500 dark:text-gray-950">ثبت نوبت</button></form>
        <form v-else-if="dialog === 'patient'" class="space-y-3" @submit.prevent="addPatient"><input v-model="patientForm.name" required placeholder="نام و نام خانوادگی" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model="patientForm.phone" required placeholder="شماره تماس" dir="ltr" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model="patientForm.email" type="email" placeholder="ایمیل" dir="ltr" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model="patientForm.diagnosis" placeholder="تشخیص یا علت مراجعه" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><button class="min-h-11 w-full rounded-xl bg-primary-700 font-bold text-white dark:bg-primary-500 dark:text-gray-950">ثبت بیمار</button></form>
        <form v-else-if="dialog === 'therapist'" class="space-y-3" @submit.prevent="addTherapist"><input v-model="therapistForm.name" required placeholder="نام درمانگر" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model="therapistForm.specialty" required placeholder="تخصص" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model="therapistForm.phone" placeholder="شماره تماس" dir="ltr" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><button class="min-h-11 w-full rounded-xl bg-primary-700 font-bold text-white dark:bg-primary-500 dark:text-gray-950">افزودن درمانگر</button></form>
        <form v-else class="space-y-3" @submit.prevent="addService"><input v-model="serviceForm.name" required placeholder="عنوان خدمت" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model.number="serviceForm.duration" required type="number" min="1" placeholder="مدت (دقیقه)" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><input v-model.number="serviceForm.price" required type="number" min="1" placeholder="تعرفه (تومان)" class="w-full rounded-xl border bg-white px-4 py-3 dark:border-gray-700 dark:bg-gray-950"/><button class="min-h-11 w-full rounded-xl bg-primary-700 font-bold text-white dark:bg-primary-500 dark:text-gray-950">افزودن خدمت</button></form>
    </div>
    </div>
    <div v-if="deleteTarget" class="fixed inset-0 z-[70] flex items-end justify-center bg-gray-950/60 p-0 backdrop-blur-sm sm:items-center sm:p-4" @click.self="deleteTarget = null">
      <section role="alertdialog" aria-modal="true" aria-labelledby="delete-title" class="w-full max-w-md rounded-t-3xl border border-gray-100 bg-white p-6 shadow-2xl dark:border-gray-800 dark:bg-gray-900 sm:rounded-3xl">
        <span class="flex h-12 w-12 items-center justify-center rounded-2xl bg-rose-50 text-rose-600 dark:bg-rose-950/50 dark:text-rose-400"><LucideIcon name="Trash2" class="h-5 w-5" /></span>
        <h2 id="delete-title" class="mt-4 text-lg font-extrabold">حذف {{ deleteTarget.type === 'patient' ? 'بیمار' : deleteTarget.type === 'therapist' ? 'درمانگر' : 'خدمت' }}</h2>
        <p class="mt-2 text-sm leading-6 text-gray-600 dark:text-gray-300">از حذف «{{ deleteTarget.name }}» مطمئن هستید؟ این مورد از فهرست این بخش پاک می‌شود.</p>
        <div class="mt-6 flex gap-3"><button class="min-h-11 flex-1 rounded-xl border border-gray-200 px-4 text-sm font-semibold text-gray-700 transition hover:bg-gray-50 dark:border-gray-700 dark:text-gray-300 dark:hover:bg-gray-800" @click="deleteTarget = null">انصراف</button><button class="inline-flex min-h-11 flex-1 items-center justify-center gap-2 rounded-xl bg-rose-600 px-4 text-sm font-bold text-white transition hover:bg-rose-700 focus:outline-none focus:ring-4 focus:ring-rose-500/20" @click="deleteRecord"><LucideIcon name="Trash2" class="h-4 w-4" /> حذف</button></div>
      </section>
    </div>
    </Teleport>
  </div>
</template>

